package com.moishow.identity;
import org.springframework.context.annotation.Profile;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @Profile("db") @RequestMapping("/api/v1")
class CommunityController {
 final Commands commands;final CommunityService service;final CommunityGroups groups;CommunityController(Commands commands,CommunityService service,CommunityGroups groups){this.commands=commands;this.service=service;this.groups=groups;}
 record PostForm(UUID clubId,String body,String kind,List<UUID> photoIds){} record BodyForm(String body){} record ToggleForm(Boolean enabled){} record DirectForm(UUID userId,String body){} record EditForm(Long version,String body,List<UUID> photoIds){} record GroupForm(String title,List<UUID> userIds){} record InviteForm(List<UUID> userIds){}
 @GetMapping("/feed/posts") Object posts(@AuthenticationPrincipal Actor a,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return service.posts(a,offset,limit);}
 @GetMapping("/feed/posts/{id}") Object getPost(@AuthenticationPrincipal Actor a,@PathVariable UUID id){return service.getPost(a,id);}
 @PostMapping("/feed/posts") Object post(@AuthenticationPrincipal Actor a,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody PostForm b){return commands.run(a,"feed:create",k,b,()->service.createPost(a,b));}
 @PostMapping("/feed/posts/{id}/{action:edit|delete}") Object edit(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody EditForm b){return commands.run(a,"feed:"+id+":"+action,k,b,()->service.editPost(a,id,b,action.equals("delete")));}
 @PostMapping("/feed/comments/{id}/{action:edit|delete}") Object editComment(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody EditForm b){return commands.run(a,"comments:"+id+":"+action,k,b,()->service.editComment(a,id,b,action.equals("delete")));}
 @PostMapping("/feed/posts/{id}/like") Object like(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody ToggleForm b){return commands.run(a,"feed:"+id+":like",k,b,()->service.like(a,id,b));}
 @GetMapping("/feed/posts/{id}/comments") Object comments(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return service.comments(a,id,offset,limit);}
 @PostMapping("/feed/posts/{id}/comments") Object comment(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody BodyForm b){return commands.run(a,"feed:"+id+":comment",k,b,()->service.comment(a,id,b));}
 @PostMapping("/users/{id}/{kind:follow|block}") Object relation(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String kind,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody ToggleForm b){return commands.run(a,"users:"+id+":"+kind,k,b,()->service.relation(a,id,kind,b));}
 @GetMapping("/chat/rooms") Object rooms(@AuthenticationPrincipal Actor a,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return service.rooms(a,offset,limit);}
 @GetMapping("/chat/requests") Object requests(@AuthenticationPrincipal Actor a,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return service.requests(a,offset,limit);}
 @PostMapping("/chat/direct") Object direct(@AuthenticationPrincipal Actor a,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody DirectForm b){return commands.run(a,"chat:direct",k,b,()->service.direct(a,b));}
 @PostMapping("/chat/rooms/{id}/{action:accept|decline}") Object accept(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody Map<String,Object> b){return commands.run(a,"chat:"+id+":"+action,k,b,()->service.accept(a,id,action.equals("decline")));}
 @GetMapping("/chat/rooms/{id}/messages") Object messages(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestParam(defaultValue="0")long after,@RequestParam(defaultValue="200")int limit){return service.messages(a,id,after,limit);}
 @PostMapping("/chat/rooms/{id}/messages") Object send(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody BodyForm b){return commands.run(a,"chat:"+id+":message",k,b,()->service.send(a,id,b));}
 @PostMapping("/chat/groups") Object group(@AuthenticationPrincipal Actor a,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody GroupForm b){return commands.run(a,"chat:group",k,b,()->groups.create(a,b));}
 @GetMapping("/chat/invitations") Object invitations(@AuthenticationPrincipal Actor a,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return groups.invitations(a,offset,limit);}
 @PostMapping("/chat/rooms/{id}/invitations") Object invite(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody InviteForm b){return commands.run(a,"chat:"+id+":invite",k,b,()->groups.invite(a,id,b));}
 @PostMapping("/chat/rooms/{id}/invitations/{action:accept|decline}") Object groupDecision(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody Map<String,Object> b){return commands.run(a,"chat:"+id+":invitation:"+action,k,b,()->groups.decide(a,id,action.equals("decline")));}
 @PostMapping("/chat/rooms/{id}/leave") Object leave(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String k,@RequestBody Map<String,Object> b){return commands.run(a,"chat:"+id+":leave",k,b,()->groups.leave(a,id));}
 @GetMapping("/chat/rooms/{id}/members") Object members(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="50")int limit){return groups.members(a,id,offset,limit);}
}
